    automatic logic canStart;
    automatic logic _GEN_6;
    canStart = canStart_REG & ~reset;
    _GEN_6 = io_canStart & io_icache_req_ready;
    if (reset) begin
      pc <= 32'h80000000;
      state <= 2'h0;
      ifid_reg_inst <= 32'h0;
      ifid_reg_valid <= 1'h0;
      ifid_reg_pc <= 32'h0;
      ifid_reg_predicted_taken <= 1'h0;
      ifid_reg_predicted_target <= 32'h0;
    end
    else begin
      automatic logic _GEN_7;
      _GEN_7 = branch | ~(|state) | ~_GEN_4 | io_signal_fetchUnitSignal_allow_to_go;
      if (branch) begin
        if (_bpu_io_flush_req) begin
          if (io_bpu_feedback_valid)
            pc <= io_bpu_feedback_actual_target;
          else
            pc <= _next_pc_T;
        end
        else
          pc <= io_signal_branchControl_target;
        state <= 2'h0;
      end
      else if (|state) begin
        if (_GEN_4)
